INSERT INTO relic_sets (name, kind, bonus_2pc, bonus_4pc, icon_path) VALUES
  ('Amphoreus, The Eternal Land', 'Ornament', 'Increases the wearer''s CRIT Rate by 8%. While the wearer''s memosprite is on the field, increases all allies'' SPD by 8%. This effect cannot be stacked.', NULL, 'assets/images/relic_amphoreus_the_eternal_land.png'),
  ('Arcadia of Woven Dreams', 'Ornament', 'When the number of ally targets on the field is not equal to 4, for every 1 additional/missing ally target, increases the DMG dealt by the wearer and their memosprite by 9%/12%, stacking up to 4/3 time(s).', NULL, 'assets/images/relic_arcadia_of_woven_dreams.png'),
  ('Belobog of the Architects', 'Ornament', 'Increases the wearer''s DEF by 15%. When the wearer''s Effect Hit Rate is 50% or higher, the wearer gains an extra 15% DEF.', NULL, 'assets/images/relic_belobog_of_the_architects.png'),
  ('Bone Collection''s Serene Demesne', 'Ornament', 'Increases the wearer''s Max HP by 12%. When the wearer''s Max HP is 5000 or higher, increases the wearer''s and their memosprite''s CRIT DMG by 28%.', NULL, 'assets/images/relic_bone_collection_s_serene_demesne.png'),
  ('Broken Keel', 'Ornament', 'Increases the wearer''s Effect RES by 10%. When the wearer''s Effect RES is at 30% or higher, all allies'' CRIT DMG increases by 10%.', NULL, 'assets/images/relic_broken_keel.png'),
  ('Celestial Differentiator', 'Ornament', 'Increases the wearer''s CRIT DMG by 16%. When the wearer''s current CRIT DMG reaches 120% or higher, after entering battle, the wearer''s CRIT Rate increases by 60% until the end of their first attack.', NULL, 'assets/images/relic_celestial_differentiator.png'),
  ('City of Converging Stars', 'Ornament', 'When the wearer uses Follow-Up ATK, increases ATK by 24% for 2 turn(s). When an enemy target gets defeated, increases CRIT DMG for all allies by 12% in the current battle. This effect cannot stack.', NULL, 'assets/images/relic_city_of_converging_stars.png'),
  ('Cosmic Life Sciences Institute', 'Ornament', 'When entering combat, if the wearer''s Max Energy is greater than or equal to 200, for every 1 excess point, increases the wearer''s DMG dealt by 0.2%, up to a max increase of 32%.', NULL, 'assets/images/relic_cosmic_life_sciences_institute.png'),
  ('Duran, Dynasty of Running Wolves', 'Ornament', 'When an ally character uses a Follow-Up ATK, the wearer gains 1 stack of "Merit," stacking up to 5 time(s). Each stack of "Merit" increases the DMG dealt by the wearer''s Follow-Up ATKs by 5%. When there are 5 stacks, additionally increases the wearer''s CRIT DMG by 25%.', NULL, 'assets/images/relic_duran_dynasty_of_running_wolves.png'),
  ('Fallen Star Anchorage', 'Ornament', 'Increases the wearer''s CRIT Rate by 8%. When entering combat, if the wearer and another teammate are both Trailblaze Companions characters, increases the wearer''s CRIT DMG by 32%.', NULL, 'assets/images/relic_fallen_star_anchorage.png'),
  ('Firmament Frontline: Glamoth', 'Ornament', 'Increases the wearer''s ATK by 12%. When the wearer''s SPD is equal to or higher than 135/160, the wearer deals 12%/18% more DMG.', NULL, 'assets/images/relic_firmament_frontline_glamoth.png'),
  ('Fleet of the Ageless', 'Ornament', 'Increases the wearer''s Max HP by 12%. When the wearer''s SPD reaches 120 or higher, all allies'' ATK increases by 8%.', NULL, 'assets/images/relic_fleet_of_the_ageless.png'),
  ('Forge of the Kalpagni Lantern', 'Ornament', 'Increases the wearer''s SPD by 6%. When the wearer hits an enemy target that has Fire Weakness, the wearer''s Break Effect increases by 40%, lasting for 1 turn(s).', NULL, 'assets/images/relic_forge_of_the_kalpagni_lantern.png'),
  ('Giant Tree of Rapt Brooding', 'Ornament', 'Increases the wearer''s SPD by 6%. When the wearer''s SPD is 135/180 or higher, the wearer and their memosprite''s Outgoing Healing increases by 12%/20%.', NULL, 'assets/images/relic_giant_tree_of_rapt_brooding.png'),
  ('God''s Moment of Joy', 'Ornament', 'Increases the wearer''s SPD by 6%. When the wearer''s Elation stat reaches 40% or higher, advances the wearer''s action by 40% immediately upon entering combat.', NULL, 'assets/images/relic_god_s_moment_of_joy.png'),
  ('Inert Salsotto', 'Ornament', 'Increases the wearer''s CRIT Rate by 8%. When the wearer''s current CRIT Rate reaches 50% or higher, the DMG dealt by the wearer''s Ultimate and Follow-Up ATK increases by 15%.', NULL, 'assets/images/relic_inert_salsotto.png'),
  ('Izumo Gensei and Takama Divine Realm', 'Ornament', 'Increases the wearer''s ATK by 12%. When entering battle, if at least one teammate follows the same Path as the wearer, then the wearer''s CRIT Rate increases by 12%.', NULL, 'assets/images/relic_izumo_gensei_and_takama_divine_realm.png'),
  ('Lushaka, the Sunken Seas', 'Ornament', 'Increases the wearer''s Energy Regeneration Rate by 5%. If the wearer is not the first character in the team lineup, then increases the ATK of the first character in the team lineup by 12%.', NULL, 'assets/images/relic_lushaka_the_sunken_seas.png'),
  ('Pan-Cosmic Commercial Enterprise', 'Ornament', 'Increases the wearer''s Effect Hit Rate by 10%. Meanwhile, the wearer''s ATK increases by an amount that is equal to 25% of the current Effect Hit Rate, up to a maximum increase of 25%.', NULL, 'assets/images/relic_pan_cosmic_commercial_enterprise.png'),
  ('Penacony, Land of the Dreams', 'Ornament', 'Increases wearer''s Energy Regeneration Rate by 5%. Increases DMG by 10% for all other allies that are of the same Type as the wearer.', NULL, 'assets/images/relic_penacony_land_of_the_dreams.png'),
  ('Punklorde Stage Zero', 'Ornament', 'Increases the wearer''s Elation by 8%. When Elation reaches 40%/80% for the first time in combat, increases the wearer''s CRIT DMG by 20%/32%.', NULL, 'assets/images/relic_punklorde_stage_zero.png'),
  ('Revelry by the Sea', 'Ornament', 'Increases the wearer''s ATK by 12%. When the wearer''s ATK is higher than or equal to 2400/3600, increases the DoT DMG dealt by 12%/24% respectively.', NULL, 'assets/images/relic_revelry_by_the_sea.png'),
  ('Rutilant Arena', 'Ornament', 'Increases the wearer''s CRIT Rate by 8%. When the wearer''s current CRIT Rate reaches 70% or higher, DMG dealt by Basic ATK and Skill increases by 20%.', NULL, 'assets/images/relic_rutilant_arena.png'),
  ('Sigonia, the Unclaimed Desolation', 'Ornament', 'Increases the wearer''s CRIT Rate by 4%. When an enemy target gets defeated, the wearer''s CRIT DMG increases by 4%, stacking up to 10 time(s).', NULL, 'assets/images/relic_sigonia_the_unclaimed_desolation.png'),
  ('Space Sealing Station', 'Ornament', 'Increases the wearer''s ATK by 12%. When the wearer''s SPD reaches 120 or higher, the wearer''s ATK increases by an extra 12%.', NULL, 'assets/images/relic_space_sealing_station.png'),
  ('Sprightly Vonwacq', 'Ornament', 'Increases the wearer''s Energy Regeneration Rate by 5%. When the wearer''s SPD reaches 120 or higher, the wearer''s action is Advanced Forward by 40% immediately upon entering battle.', NULL, 'assets/images/relic_sprightly_vonwacq.png'),
  ('Subspace ASC Center', 'Ornament', 'Increases the wearer''s SPD by 6%. When the wearer''s SPD reaches 145 or higher, increases all allies'' Break Effect by 18% after entering combat. This effect cannot stack.', NULL, 'assets/images/relic_subspace_asc_center.png'),
  ('Talia: Kingdom of Banditry', 'Ornament', 'Increases the wearer''s Break Effect by 16%. When the wearer''s SPD reaches 145 or higher, the wearer''s Break Effect increases by an extra 20%.', NULL, 'assets/images/relic_talia_kingdom_of_banditry.png'),
  ('Tengoku@Livestream', 'Ornament', 'Increases the wearer''s CRIT DMG by 16%. If 3 or more Skill Points are consumed in the same turn, additionally increases the wearer''s CRIT DMG by 32%, lasting for 3 turns.', NULL, 'assets/images/relic_tengoku_livestream.png'),
  ('The Wondrous BananAmusement Park', 'Ornament', 'Increases the wearer''s CRIT DMG by 16%. When a target summoned by the wearer is on the field, CRIT DMG additionally increases by 32%.', NULL, 'assets/images/relic_the_wondrous_bananamusement_park.png'),
  ('As Navigator Isee Sees It', 'Relikt', 'Increases ATK by 12%.', 'When the wearer enters combat or uses Skill, the DMG dealt by their Skill and Ultimate increases by 18%, stacking up to 3 time(s). At the start of the wearer''s turn or after using Ultimate, removes 1 stack(s) of this effect.', 'assets/images/relic_as_navigator_isee_sees_it.png'),
  ('Band of Sizzling Thunder', 'Relikt', 'Increases Lightning DMG by 10%.', 'When the wearer uses their Skill, increases the wearer''s ATK by 20% for 1 turn(s).', 'assets/images/relic_band_of_sizzling_thunder.png'),
  ('Champion of Streetwise Boxing', 'Relikt', 'Increases Physical DMG by 10%.', 'After the wearer attacks or is hit, their ATK increases by 5% for the rest of the battle. This effect can stack up to 5 time(s).', 'assets/images/relic_champion_of_streetwise_boxing.png'),
  ('Divine-Querying Master Smith', 'Relikt', 'Increases Max HP by 12%.', 'Increases the wearer''s CRIT DMG dealt to enemy targets in the DEF reduction state by 28%. After the wearer inflicts the DEF reduction state on an enemy target, all allies gain "Comburent" for 2 turn(s). This effect cannot be stacked. The DMG dealt by ally targets with "Comburent" increases by 15%. This effect can be triggered again after the wearer uses an attack.', 'assets/images/relic_divine_querying_master_smith.png'),
  ('Diviner of Distant Reach', 'Relikt', 'Increases SPD by 6%.', 'Before entering combat, if the wearer''s SPD is greater than or equal to 120/160, increases the wearer''s CRIT Rate by 10%/18%. When the wearer uses Elation Skill for the first time in each battle, increases all allies'' Elation by 10%. This effect cannot stack.', 'assets/images/relic_diviner_of_distant_reach.png'),
  ('Dreamlit Actor', 'Relikt', 'Increases SPD by 6%.', 'When the wearer uses their Skill or Ultimate on one other ally target, increases the ability target''s Elation by 16%, lasting for 3 turn(s). If the wearer has 10 or more points of Certified Banger, additionally increases all ally targets'' CRIT DMG by 12%, lasting for 3 turn(s).', 'assets/images/relic_dreamlit_actor.png'),
  ('Eagle of Twilight Line', 'Relikt', 'Increases Wind DMG by 10%.', 'After the wearer uses their Ultimate, their action is Advanced Forward by 25%.', 'assets/images/relic_eagle_of_twilight_line.png'),
  ('Ever-Glorious Magical Girl', 'Relikt', 'Increases CRIT DMG by 16%.', 'The Elation DMG dealt by the wearer and their memosprites ignores 10% of targets'' DEF. For every 5 accumulated Punchline allies gain, the Elation DMG dealt additionally ignores 1% of targets'' DEF, stacking up to 10 time(s).', 'assets/images/relic_ever_glorious_magical_girl.png'),
  ('Firesmith of Lava-Forging', 'Relikt', 'Increases Fire DMG by 10%.', 'Increases DMG by the wearer''s Skill by 12%. After unleashing Ultimate, increases the wearer''s Fire DMG by 12% for the next attack.', 'assets/images/relic_firesmith_of_lava_forging.png'),
  ('Genius of Brilliant Stars', 'Relikt', 'Increases Quantum DMG by 10%.', 'When the wearer deals DMG to the target enemy, ignores 10% DEF. If the target enemy has Quantum Weakness, the wearer additionally ignores 10% DEF.', 'assets/images/relic_genius_of_brilliant_stars.png'),
  ('Guard of Wuthering Snow', 'Relikt', 'Reduces DMG taken by 8%.', 'At the beginning of the turn, if the wearer''s HP percentage is equal to or less than 50%, restores HP equal to 8% of their Max HP and regenerates 5 Energy.', 'assets/images/relic_guard_of_wuthering_snow.png'),
  ('Hero of Triumphant Song', 'Relikt', 'Increases ATK by 12%.', 'While the wearer''s memosprite is on the field, increases the wearer''s SPD by 6%. When the wearer''s memosprite attacks, increases the wearer''s and memosprite''s CRIT DMG by 30%, lasting for 2 turn(s).', 'assets/images/relic_hero_of_triumphant_song.png'),
  ('Hunter of Glacial Forest', 'Relikt', 'Increases Ice DMG by 10%.', 'After the wearer uses their Ultimate, their CRIT DMG increases by 25% for 2 turn(s).', 'assets/images/relic_hunter_of_glacial_forest.png'),
  ('Iron Cavalry Against the Scourge', 'Relikt', 'Increases Break Effect by 16%.', 'If the wearer''s Break Effect is 150% or higher, the Break DMG dealt to the enemy target ignores 10% of their DEF. If the wearer''s Break Effect is 250% or higher, the Super Break DMG dealt to the enemy target additionally ignores 15% of their DEF.', 'assets/images/relic_iron_cavalry_against_the_scourge.png'),
  ('Knight of Purity Palace', 'Relikt', 'Increases DEF by 15%.', 'Increases the max DMG that can be absorbed by the Shield created by the wearer by 20%.', 'assets/images/relic_knight_of_purity_palace.png'),
  ('Longevous Disciple', 'Relikt', 'Increases Max HP by 12%.', 'When the wearer is hit or has their HP consumed by an ally or themselves, their CRIT Rate increases by 8% for 2 turn(s) and up to 2 stacks.', 'assets/images/relic_longevous_disciple.png'),
  ('Messenger Traversing Hackerspace', 'Relikt', 'Increases SPD by 6%.', 'When the wearer uses their Ultimate on an ally, SPD for all allies increases by 12% for 1 turn(s). This effect cannot be stacked.', 'assets/images/relic_messenger_traversing_hackerspace.png'),
  ('Musketeer of Wild Wheat', 'Relikt', 'Increases ATK by 12%.', 'The wearer''s SPD increases by 6% and DMG dealt by Basic ATK increases by 10%.', 'assets/images/relic_musketeer_of_wild_wheat.png'),
  ('Passerby of Wandering Cloud', 'Relikt', 'Increases Outgoing Healing by 10%.', 'At the start of the battle, immediately regenerates 1 Skill Point.', 'assets/images/relic_passerby_of_wandering_cloud.png'),
  ('Pioneer Diver of Dead Waters', 'Relikt', 'Increases DMG dealt to enemies with debuffs by 12%.', 'Increases CRIT Rate by 4%. The wearer deals 8%/12% increased CRIT DMG to enemies with at least 2/3 debuffs. After the wearer inflicts a debuff on enemy targets, the aforementioned effects increase by 100%, lasting for 1 turn(s).', 'assets/images/relic_pioneer_diver_of_dead_waters.png'),
  ('Poet of Mourning Collapse', 'Relikt', 'Increases Quantum DMG by 10%.', 'Decreases the wearer''s SPD by 8%. Before entering battle, if the wearer''s SPD is lower than 110/95, increases the wearer''s CRIT Rate by 20%/32%. This effect applies to the wearer''s memosprite at the same time.', 'assets/images/relic_poet_of_mourning_collapse.png'),
  ('Prisoner in Deep Confinement', 'Relikt', 'Increases ATK by 12%.', 'For every DoT the enemy target is afflicted with, the wearer will ignore 6% of its DEF when dealing DMG to it. This effect is valid for a max of 3 DoTs.', 'assets/images/relic_prisoner_in_deep_confinement.png'),
  ('Sacerdos'' Relived Ordeal', 'Relikt', 'Increases SPD by 6%.', 'When using Skill or Ultimate on one ally target, increases the ability target''s CRIT DMG by 18%, lasting for 2 turn(s). This effect can stack up to 2 time(s).', 'assets/images/relic_sacerdos_relived_ordeal.png'),
  ('Scholar Lost in Erudition', 'Relikt', 'Increases CRIT Rate by 8%.', 'Increases DMG dealt by Skill and Ultimate by 20%. After using Ultimate, additionally increases the DMG dealt by the next Skill by 25%.', 'assets/images/relic_scholar_lost_in_erudition.png'),
  ('Self-Enshrouded Recluse', 'Relikt', 'The provided Shield Effect increases by 10%.', 'Increases the Shield Effect provided by the wearer by 12%. When an ally target holds a Shield provided by the wearer, the ally target''s CRIT DMG increases by 15%.', 'assets/images/relic_self_enshrouded_recluse.png'),
  ('The Ashblazing Grand Duke', 'Relikt', 'Increases the DMG dealt by Follow-Up ATK by 20%.', 'When the wearer uses a Follow-Up ATK, increases the wearer''s ATK by 6% for every time the Follow-Up ATK deals DMG. This effect can stack up to 8 time(s) and lasts for 3 turn(s). This effect is removed the next time the wearer uses a Follow-Up ATK.', 'assets/images/relic_the_ashblazing_grand_duke.png'),
  ('The Edacious Heretic', 'Relikt', 'Increases CRIT DMG by 16%.', 'Increases DMG dealt by the wearer''s Basic ATK by 36%. When the wearer uses Basic ATK, increases the wearer''s ATK by 20%, lasting for 2 turn(s).', 'assets/images/relic_the_edacious_heretic.png'),
  ('The Wind-Soaring Valorous', 'Relikt', 'Increases ATK by 12%.', 'Increases the wearer''s CRIT Rate by 6%. After the wearer uses a Follow-Up ATK, increases DMG dealt by Ultimate by 36%, lasting for 1 turn(s).', 'assets/images/relic_the_wind_soaring_valorous.png'),
  ('Thief of Shooting Meteor', 'Relikt', 'Increases Break Effect by 16%.', 'Increases the wearer''s Break Effect by 16%. After the wearer inflicts Weakness Break on an enemy, regenerates 3 Energy.', 'assets/images/relic_thief_of_shooting_meteor.png'),
  ('Warrior Goddess of Sun and Thunder', 'Relikt', 'Increases SPD by 6%.', 'When the wearer or their memosprite provides healing to ally targets other than themselves, the wearer gains "Gentle Rain," which lasts for 2 turn(s) and can only trigger once per turn. While the wearer has "Gentle Rain," SPD increases by 6% and all allies'' CRIT DMG increases by 15%. This effect cannot stack.', 'assets/images/relic_warrior_goddess_of_sun_and_thunder.png'),
  ('Wastelander of Banditry Desert', 'Relikt', 'Increases Imaginary DMG by 10%.', 'When dealing DMG to debuffed enemy targets, the wearer has their CRIT Rate increased by 10%. And when they deal DMG to Imprisoned enemy targets, their CRIT DMG increases by 20%.', 'assets/images/relic_wastelander_of_banditry_desert.png'),
  ('Watchmaker, Master of Dream Machinations', 'Relikt', 'Increases Break Effect by 16%.', 'When the wearer uses their Ultimate on an ally, all allies'' Break Effect increases by 30% for 2 turn(s). This effect cannot be stacked.', 'assets/images/relic_watchmaker_master_of_dream_machinations.png'),
  ('Wavestrider Captain', 'Relikt', 'Increases CRIT DMG by 16%.', 'When the wearer becomes the target of another ally target''s ability, gains 1 stack of "Help," stacking up to 2 time(s). If there are 2 stack(s) of "Help" when the wearer uses their Ultimate, consumes all "Help" to increase the wearer''s ATK by 48% for 1 turn(s).', 'assets/images/relic_wavestrider_captain.png'),
  ('World-Remaking Deliverer', 'Relikt', 'Increases CRIT Rate by 8%.', 'After the wearer uses Basic ATK or Skill, if the wearer''s memosprite is on the field, increases Max HP of the wearer and their memosprite by 24%, and increases all allies'' DMG dealt by 15%, lasting until after the wearer''s next use of Basic ATK or Skill.', 'assets/images/relic_world_remaking_deliverer.png')
