-- Erzeugt von web/tools/make_seed.py aus shared/stammdaten.json. Nicht von Hand ändern.
SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE element=VALUES(element), path=VALUES(path), rarity=VALUES(rarity), icon_path=VALUES(icon_path);

ON DUPLICATE KEY UPDATE path=VALUES(path), rarity=VALUES(rarity), icon_path=VALUES(icon_path);

ON DUPLICATE KEY UPDATE kind=VALUES(kind), bonus_2pc=VALUES(bonus_2pc), bonus_4pc=VALUES(bonus_4pc), icon_path=VALUES(icon_path);
